def answer_stripes_below_beside_girl(image):
    image_patch = ImagePatch(image)
    girl_patches = image_patch.find("girl")

    if not girl_patches:
        return "No girl found in the image."

    girl_patch = girl_patches[0]
    girl_center_y = (girl_patch.lower + girl_patch.upper) / 2

    stripe_patches = image_patch.find("striped")
    stripe_below_girl = [stripe for stripe in stripe_patches if stripe.upper < girl_center_y]

    if stripe_below_girl:
        stripe_patch = stripe_below_girl[0]
        stripe_center_x = (stripe_patch.left + stripe_patch.right) / 2

        girl_center_x = (girl_patch.left + girl_patch.right) / 2

        if abs(stripe_center_x - girl_center_x) < abs(girl_center_x - stripe_center_x):
            return "The striped thing is below and beside the girl."
        else:
            return "The striped thing is below but not beside the girl."
    else:
        return "No striped thing found below the girl."

