def execute_command(image) -> ImagePatch:
    image_patch = ImagePatch(image)
    people = image_patch.find("person")
    if not people: return image_patch

    # Find the person closest to the 9 o'clock position
    def angle_to_position(angle):
        angle = math.radians(angle)
        return (math.cos(angle), math.sin(angle))

    target_angle = 9 * (360 / 12)  # 9 o'clock in degrees
    target_position = angle_to_position(target_angle)

    def distance_to_target(person):
        person_position = (person.horizontal_center, person.vertical_center)
        return math.sqrt((person_position[0] - target_position[0])**2 + (person_position[1] - target_position[1])**2)

    people.sort(key=distance_to_target)
    return people[0]

